#!/bin/zsh
# native_disp_plant.sh - planted breaks for tests/native_disp_test.cpp (build 0.0.613, #11 step 11h.2: the display pipe).
# Discipline: copy the sources the test reads into a scratch tree, apply ONE break to the REAL code (a header, a flow, the kernel glue, a call site), build the real test against the copy and demand
# it FAILS (a compile error, a failing check, a crash or a hang all count). A plant whose text is not found exactly once is itself reported as an escape. The CONTROL (no break) must pass.
#   run from anywhere:  src/navi48-bringup/tests/native_disp_plant.sh [first-plant-id last-plant-id]
# The table and the runner are Python (the breaks are multi-line and quote-heavy); this wrapper only hands it the tree root.
ROOT="$(cd "$(dirname "$0")/../../.." && pwd)"
exec python3 -u - "$ROOT" "${1:-0}" "${2:-9999}" <<'PY'
import os, shutil, subprocess, sys, tempfile, time

ROOT, FIRST, LAST = sys.argv[1], int(sys.argv[2]), int(sys.argv[3])
K = 'src/navi48-bringup'
FILES = [f'{K}/src/dcn/navi48_dispread.h', f'{K}/src/dcn/navi48_dmubcmd.h', f'{K}/src/amd/native_disp_pure.h', f'{K}/src/amd/native_disp_flow.h', f'{K}/src/amd/native_metal_pure.h', f'{K}/src/amd/native_disp.cpp', f'{K}/src/amd/native_disp.h',
         f'{K}/src/amd/native_s1c.h', f'{K}/src/Navi48MetalNub.cpp', f'{K}/src/Navi48NativeClient.cpp', f'{K}/src/dcn/navi48_dcn.cpp', f'{K}/src/dcn/navi48_dcn.hpp', f'{K}/src/Navi48Bringup.cpp', f'{K}/src/Navi48UserClient.cpp', f'{K}/src/Navi48Bringup.hpp', f'{K}/src/Navi48MetalOps.h',
         f'{K}/Info.plist', f'{K}/tests/native_disp_test.cpp', f'{K}/tests/native_fb_monb_battery.h', f'{K}/tests/native_disp_plant.sh', 'tools/pc/navi48test.c',
         # 0.0.652 (M5): native_disp_pure.h includes the disp2 header and native_fb_pure.h (-> Navi48DisplayOps.h) (the control FAILED unmodified at 0.0.651 without the disp2 header); the M section of the test reads the nub, the Makefile, the allocator and the variants
         f'{K}/src/dcn/navi48_disp2.h', f'{K}/src/amd/native_fb_pure.h', f'{K}/src/Navi48DisplayOps.h', f'{K}/src/Navi48DisplayNub.cpp', f'{K}/src/Navi48DisplayNub.hpp', f'{K}/Makefile', f'{K}/src/amd/native_s1c.cpp',
         'variants/configs/stage17-native-1440-metal-disp-amfi-fb2.plist', 'variants/configs/stage17-native-1440-metal-disp-amfi-disp2.plist',
         # 0.0.659 (M6 Stage 1a): the pure header, the OFF-identity battery, the AGDC glue and its pure header, the ABI header and the two variants section N reads
         f'{K}/src/amd/native_m6_pure.h', f'{K}/tests/native_m6_off_battery.h', f'{K}/src/apple/DisplayPipeGuard.cpp', f'{K}/src/apple/display_pipe_guard.h', f'{K}/src/Navi48NativeABI.h',
         'variants/configs/stage17-native-1440-metal-disp-amfi-ms-apps.plist', 'variants/configs/stage17-native-1440-metal-disp-amfi-m6.plist']
FBP, DNUB, DOPS, MPURE, MK, VAR = (f'{K}/src/amd/native_fb_pure.h', f'{K}/src/Navi48DisplayNub.cpp', f'{K}/src/Navi48DisplayOps.h', f'{K}/src/amd/native_metal_pure.h', f'{K}/Makefile', 'variants/configs/stage17-native-1440-metal-disp-amfi-fb2.plist')
AUXOPS = 'tools/native/navi48accel/src/Navi48DisplayOps.h'
PURE, FLOW, GLUE, NUB, BRG, UCL, CLI, PLIST = (f'{K}/src/amd/native_disp_pure.h', f'{K}/src/amd/native_disp_flow.h', f'{K}/src/amd/native_disp.cpp', f'{K}/src/Navi48MetalNub.cpp',
                                              f'{K}/src/Navi48Bringup.cpp', f'{K}/src/Navi48UserClient.cpp', 'tools/pc/navi48test.c', f'{K}/Info.plist')
AUX = os.environ.get('N48_AUX_ROOT', ROOT)

scr = tempfile.mkdtemp(prefix='ndisp-plant.')
def fresh():
    shutil.rmtree(scr, ignore_errors=True)
    for f in FILES:
        d = os.path.join(scr, f); os.makedirs(os.path.dirname(d), exist_ok=True); shutil.copy(os.path.join(ROOT, f), d)
    for an in ('Navi48MetalOps.h', 'Navi48DisplayOps.h'):
        a = os.path.join(AUX, 'tools/native/navi48accel/src/' + an)
        if os.path.exists(a):
            d = os.path.join(scr, 'tools/native/navi48accel/src/' + an); os.makedirs(os.path.dirname(d), exist_ok=True); shutil.copy(a, d)
def build_run():
    r = subprocess.run(['clang++', '-std=c++17', '-Wall', '-Wextra', '-O1', '-fsanitize=address,undefined', '-I', f'{K}/src', '-I', f'{K}/src/amd', f'{K}/tests/native_disp_test.cpp', '-o', os.path.join(scr, 't')],
                       cwd=scr, capture_output=True, text=True)
    if r.returncode != 0:
        first = next((l for l in r.stderr.splitlines() if 'error' in l), '')
        return 2, 'CAUGHT at compile time: ' + first[:140]
    try:
        r = subprocess.run([os.path.join(scr, 't'), '.'], cwd=scr, capture_output=True, text=True, timeout=60)
    except subprocess.TimeoutExpired:
        return 1, 'CAUGHT by a hang'
    if r.returncode == 0: return 0, 'the suite passed: ' + r.stdout.strip().splitlines()[-1]
    if r.returncode < 0: return 1, 'CAUGHT by a crash (signal %d)' % -r.returncode
    fails = [l for l in r.stdout.splitlines() if l.startswith('FAIL')]
    return 1, 'CAUGHT by %d check(s); first: %s' % (len(fails), (fails[0] if fails else r.stdout.strip().splitlines()[-1])[:120])

total = escaped = 0
def control():
    global total, escaped
    fresh(); total += 1
    rc, msg = build_run()
    if rc != 0: print('CONTROL: *** FAILED UNMODIFIED (%s) ***' % msg); escaped += 1
    else: print('CONTROL: ' + msg)
def plant(pid, path, desc, old, new):
    global total, escaped
    if pid < FIRST or pid > LAST: return
    fresh(); total += 1
    f = os.path.join(scr, path); s = open(f).read()
    n = s.count(old)
    if n != 1:
        print('PLANT %d: %s: PLANT TEXT NOT FOUND EXACTLY ONCE (%d)' % (pid, desc, n)); escaped += 1; return
    open(f, 'w').write(s.replace(old, new))
    t0 = time.time(); rc, msg = build_run(); dt = time.time() - t0
    if rc == 0: print('PLANT %d: %s: *** ESCAPED (%s) *** [%.1fs]' % (pid, desc, msg, dt)); escaped += 1
    else: print('PLANT %d: %s: %s [%.1fs]' % (pid, desc, msg, dt))

control()
# ---- the pure decisions --------------------------------------------------------------------------------------------------------------------------------------------------
plant(1, PURE, 'a display verb is admitted with the boot-arg OFF (action bound)', 'return action <= kLastOldAction || (latchOn && (action <= kLastAction || action == kActFbPublish || action == kActM6Stat || action == kActM6XStat || action == kActVramStat));', 'return action <= kLastOldAction || (action <= kLastAction || action == kActFbPublish || action == kActM6Stat || action == kActM6XStat || action == kActVramStat);')
plant(2, PURE, 'a native exemption is granted with the boot-arg OFF', 'constexpr bool native_exempt(bool latchOn, uint32_t action, uint64_t arg) { return latchOn && verb_args_ok(action, arg); }', 'constexpr bool native_exempt(bool latchOn, uint32_t action, uint64_t arg) { (void)latchOn; return verb_args_ok(action, arg); }')
plant(3, PURE, 'fbname 2 is exempt', '(action == kActFbname && arg <= 1ull)', '(action == kActFbname && arg <= 2ull)')
plant(4, PURE, 'the OFF ops table is published as ABI 2 (native_open would be outside it)', ': OpsShape{ N48_METAL_ABI, N48_METAL_OPS_V3, 0u }', ': OpsShape{ 2u, N48_METAL_OPS_V3, 0u }')
plant(5, PURE, 'the OFF ops table keeps the 144-byte size (native_open would be outside it)', ': OpsShape{ N48_METAL_ABI, N48_METAL_OPS_V3, 0u }', ': OpsShape{ N48_METAL_ABI, N48_METAL_OPS_V2, 0u }')
plant(6, PURE, 'the OFF ops table carries the display flag', ': OpsShape{ N48_METAL_ABI, N48_METAL_OPS_V3, 0u }', ': OpsShape{ N48_METAL_ABI, N48_METAL_OPS_V3, N48_DISP_F_ON }')
plant(7, PURE, 'the runtime fact bits leak into the OFF mask', 'return latchOn ? (baseMask | (runtimeBits & kNeedFacts)) : baseMask;', 'return (baseMask | (runtimeBits & kNeedFacts));')
plant(8, PURE, 'facts_ok needs only the RESOURCE bit', 'return (mask & kNeedFacts) == kNeedFacts;', 'return (mask & N48_FACT_RESOURCE) != 0u;')
plant(9, PURE, 'the needed facts drop VIDMEMORY', 'constexpr uint32_t kNeedFacts = N48_FACT_RESOURCE | N48_FACT_SYSMEMORY | N48_FACT_VIDMEMORY;', 'constexpr uint32_t kNeedFacts = N48_FACT_RESOURCE | N48_FACT_SYSMEMORY;')
plant(10, PURE, 'the gate byte is not range checked', 'atCfgF0 == 0x480000u && atCfgF4Low == 8u && pipeGate <= 1u;', 'atCfgF0 == 0x480000u && atCfgF4Low == 8u;')
plant(11, PURE, 'the config +0x08 control is skipped', 'atCfgF0 == 0x480000u && atCfgF4Low == 8u && pipeGate <= 1u;', 'atCfgF4Low == 8u && pipeGate <= 1u;')
plant(12, PURE, 'a pipe the aux kext never traced counts as verified', 'p.classOurs && p.traced && p.backAccel', 'p.classOurs && p.backAccel')
plant(13, PURE, 'several pipes count as verified', 'p.dmReadable && p.count == 1u && p.havePipe', 'p.dmReadable && p.count >= 1u && p.havePipe')
plant(14, PURE, 'the framebuffer back-pointer is not checked', 'p.backAccel && p.backDm && p.backFb && p.fbOurs;', 'p.backAccel && p.backDm && p.fbOurs;')
plant(15, PURE, 'a family pipe (class not ours) counts as verified', 'p.havePipe && p.classOurs && p.traced', 'p.havePipe && p.traced')
plant(16, PURE, 'adopt goes ahead over pipes that are not verified ours', 'before.count == 0u ? kOk : (before.nullPipe || n48m6::ents_any_null(before.ents)) ? kNullPipe : pipe_ok(before) ? kAlready : kHasPipes;', 'kOk;')
plant(17, PURE, 'disarm needs a pipe (arm 0 not always allowed)', 'arg > 1ull ? kBadArg : arg == 0ull ? kOk :', 'arg > 1ull ? kBadArg : arg == 0ull ? (a.pipeOk ? kOk : kNoPipe) :')
plant(18, PURE, 'arm before the pipe exists', '!a.latchOn ? kOff : !a.factsOk ? kFactsOff : !a.pipeOk ? kNoPipe : !a.accelLayoutOk ? kAccelLayout : kOk;', '!a.latchOn ? kOff : !a.factsOk ? kFactsOff : !a.accelLayoutOk ? kAccelLayout : kOk;')
plant(19, PURE, 'arm without the resource facts', '!a.latchOn ? kOff : !a.factsOk ? kFactsOff : !a.pipeOk', '!a.latchOn ? kOff : !a.pipeOk')
plant(20, PURE, 'arm with the boot-arg OFF', '!a.latchOn ? kOff : !a.factsOk ? kFactsOff : !a.pipeOk', '!a.factsOk ? kFactsOff : !a.pipeOk')
plant(21, PURE, 'submit returns 0 for a zero status', 'return (statusKnown && txnStatus != 0u) ? txnStatus : kWillPerform;', 'return (statusKnown && txnStatus != 0u) ? txnStatus : 0u;')
plant(22, PURE, 'submit swallows a failed prepare (ignores a nonzero status)', 'return (statusKnown && txnStatus != 0u) ? txnStatus : kWillPerform;', 'return kWillPerform;')
plant(23, PURE, 'submit returns 0 when the status is unreadable', 'return (statusKnown && txnStatus != 0u) ? txnStatus : kWillPerform;', 'return statusKnown ? ((txnStatus != 0u) ? txnStatus : kWillPerform) : 0u;')
plant(24, PURE, 'isTransactionComplete is false', 'constexpr uint64_t iscomplete_result() { return 1ull; }', 'constexpr uint64_t iscomplete_result() { return 0ull; }')
plant(25, PURE, 'copy past the console: the destination rows at the console stride are not checked', 'if ((b.height - 1ull) * b.consoleStride + row > b.consoleBytes) return kBDest;', '(void)row;')
plant(26, PURE, 'the w*h*4 console bound is off by one (a frame that exactly fills the console is refused). NOTE: dropping this check outright is an EQUIVALENT mutant, it is implied by the destination-row check once the stride is >= a row', 'if (b.width * b.height * 4ull > b.consoleBytes) return kBDest;', 'if (b.width * b.height * 4ull >= b.consoleBytes) return kBDest;')
plant(27, PURE, 'the source rows are not checked against the source length', 'if ((b.height - 1ull) * b.srcBytesPerRow + row > b.srcBytes) return kBSrc;', '(void)row;')
plant(28, PURE, 'width need not equal the console width', 'if (b.width != b.consoleWidth || b.height > b.consoleHeight) return kBGeom;', 'if (b.height > b.consoleHeight) return kBGeom;')
plant(29, PURE, 'the destination product is computed in 32 bits', 'if ((b.height - 1ull) * b.consoleStride + row > b.consoleBytes) return kBDest;', 'if ((uint32_t)((b.height - 1ull) * b.consoleStride + row) > b.consoleBytes) return kBDest;')
plant(30, PURE, 'a frame taller than the console is admitted', 'if (b.width != b.consoleWidth || b.height > b.consoleHeight) return kBGeom;', 'if (b.width != b.consoleWidth) return kBGeom;')
plant(31, PURE, 'a row wider than the scratch buffer is admitted', 'if (row > kScratchBytes) return kBGeom;', '(void)row;')
plant(32, PURE, 'a console stride narrower than a row is admitted', 'if (b.srcBytesPerRow < row || b.consoleStride < row) return kBStride;', 'if (b.srcBytesPerRow < row) return kBStride;')
plant(33, PURE, 'a source stride narrower than a row is admitted', 'if (b.srcBytesPerRow < row || b.consoleStride < row) return kBStride;', 'if (b.consoleStride < row) return kBStride;')
plant(34, PURE, 'a 2^32 operand is no longer refused up front', 'if (b.width > 0xffffffffull || b.height > 0xffffffffull || b.srcBytesPerRow > 0xffffffffull || b.consoleStride > 0xffffffffull || b.consoleHeight > 0xffffffffull) return kBBadArg;', '(void)b;')
plant(35, PURE, 'a nonzero baseOffset is admitted', 'return baseOffset == 0ull && planeCount <= 1u', 'return planeCount <= 1u')
plant(36, PURE, 'a multi-plane surface is admitted', 'planeCount <= 1u && pixelFormat', 'planeCount <= 8u && pixelFormat')
plant(37, PURE, 'any pixel format is admitted', 'pixelFormat == kFmtBGRA && bytesPerElement == 4u;', 'bytesPerElement == 4u;')
plant(38, PURE, 'any element size is admitted', 'pixelFormat == kFmtBGRA && bytesPerElement == 4u;', 'pixelFormat == kFmtBGRA;')
plant(39, PURE, 'the stride disagreement is ignored', 'return sw == rw && sh == rh && sbpr == rbpr;', 'return sw == rw && sh == rh;')
plant(40, PURE, 'the shortcut is applied when its guard bit is set', 'constexpr bool shortcut_allowed(bool sysMemFlagsKnown, bool bit4Set) { return sysMemFlagsKnown && !bit4Set; }', 'constexpr bool shortcut_allowed(bool sysMemFlagsKnown, bool bit4Set) { (void)bit4Set; return sysMemFlagsKnown; }')
plant(41, PURE, 'the shortcut is applied when the guard byte cannot be read', 'constexpr bool shortcut_allowed(bool sysMemFlagsKnown, bool bit4Set) { return sysMemFlagsKnown && !bit4Set; }', 'constexpr bool shortcut_allowed(bool sysMemFlagsKnown, bool bit4Set) { (void)sysMemFlagsKnown; return !bit4Set; }')
plant(42, PURE, 'the shortcut ignores its switch', 'in.switchOn && shortcut_allowed(in.flagsKnown, in.bit4), in.switchOn && !shortcut_allowed', 'shortcut_allowed(in.flagsKnown, in.bit4), in.switchOn && !shortcut_allowed')
plant(43, PURE, 'slot 62 handles without the IOSurface', 'Res62Plan{ in.smKnown && in.smLen != 0ull && in.surfKnown && in.surfBpr != 0ull,', 'Res62Plan{ in.smKnown && in.smLen != 0ull,')
plant(44, PURE, 'slot 62 hands out the wrong number (allocation size = bytes per row)', '(in.smKnown && in.smLen != 0ull && in.surfKnown && in.surfBpr != 0ull) ? in.smLen : 0ull,', '(in.smKnown && in.smLen != 0ull && in.surfKnown && in.surfBpr != 0ull) ? in.surfBpr : 0ull,')
plant(45, PURE, 'the stand-in does not carry the prune-skip bit', 'o[kObjFlagD] = kObjFlagDValue;', 'o[kObjFlagD] = 0u;')
plant(46, PURE, 'the stand-in fill clobbers the vtable pointer', 'for (uint32_t i = 8u; i < kObjSize; ++i) o[i] = 0u;', 'for (uint32_t i = 0u; i < kObjSize; ++i) o[i] = 0u;')
plant(47, PURE, 'the stand-in fill leaves stale bytes (+0x38 not zeroed)', 'for (uint32_t i = 8u; i < kObjSize; ++i) o[i] = 0u;', '')
plant(48, PURE, 'an empty pipe-table entry matches pointer 0', 'if (t[i] == p && p != 0ull) return (int)i;', 'if (t[i] == p) return (int)i;')
