plant(50, PURE, 'the stamp count is not clamped', 'constexpr uint32_t stamp_walk_bound(uint32_t requested) { return requested > kStampMaxSlots ? kStampMaxSlots : requested; }', 'constexpr uint32_t stamp_walk_bound(uint32_t requested) { return requested; }')
