plant(57, PURE, 'the resource system-memory offset is wrong', 'kResSysMem = 0x80u,', 'kResSysMem = 0x88u,')
plant(58, PURE, 'the transaction status offset is wrong', 'kTxnStatus = 0x58u;', 'kTxnStatus = 0x5cu;')
plant(59, PURE, 'the gate byte offset is wrong (accel+0xccf)', 'constexpr uint32_t kAccelCfgBase = 0xc88u;', 'constexpr uint32_t kAccelCfgBase = 0xc80u;')
plant(55, PURE, 'the IOSurface width offset is wrong', 'constexpr uint32_t kSurfW = 0x58u,', 'constexpr uint32_t kSurfW = 0x50u,')
