plant(63, FLOW, 'adopt probes again although the verified pipe is already there', 'if (pre == kOk && !e.request_probe()) return kProbeFailed;', 'if (!e.request_probe()) return kProbeFailed;')
plant(64, FLOW, 'adopt records a pipe that failed verification', '    if (v != kOk) return v;\n    if (!e.publish_caps())', '    if (!e.publish_caps())')
